double calculateBound(Node u, int n, int W, vector<Item>& items) {
    if (u.weight >= W) return 0;
    double bound = u.profit;
    int tw = u.weight;
    int j = u.level + 1;
    while (j < n && tw + items[j].weight <= W) {
        tw += items[j].weight;
        bound += items[j].profit;
        j++;
    }
    if (j < n) bound += (double)(W - tw) * items[j].ratio;
    return bound;
}
int knapsackBnB(int W, vector<Item>& items, int n) {
    sort(items.begin(), items.end(), [](Item& a, Item& b){ return a.ratio > b.ratio; });
    queue<Node> Q;
    Node u = {-1, 0, 0, 0};
    u.bound = calculateBound(u, n, W, items);
    Q.push(u);
    int maxProfit = 0;
    while (!Q.empty()) {
        u = Q.front(); Q.pop();
        if (u.level == n-1) continue;
        Node v;
        v.level = u.level + 1;
        v.weight = u.weight + items[v.level].weight;
        v.profit = u.profit + items[v.level].profit;
        if (v.weight <= W && v.profit > maxProfit) maxProfit = v.profit;
        v.bound = calculateBound(v, n, W, items);
        if (v.bound > maxProfit) Q.push(v);
        v.weight = u.weight; v.profit = u.profit;
        v.bound = calculateBound(v, n, W, items);
        if (v.bound > maxProfit) Q.push(v);
    }
    return maxProfit;
}

