    cost = 0
    for i in range(n):
        mn = min(matrix[i])
        if mn != INF and mn > 0:
            cost += mn
            matrix[i] = [x - mn if x != INF else INF for x in matrix[i]]
    for j in range(n):
        mn = min(matrix[i][j] for i in range(n))
        if mn != INF and mn > 0:
            cost += mn
            for i in range(n):
                if matrix[i][j] != INF: matrix[i][j] -= mn
    return cost

