int jobAssignmentBnB(vector<vector<int>>& cost, int n) {
    auto calcBound = [&](int level, vector<bool>& assigned, int curCost) {
        int bound = curCost;
        for (int i = level; i < n; i++) {
            int mn = INT_MAX;
            for (int j = 0; j < n; j++)
                if (!assigned[j]) mn = min(mn, cost[i][j]);
            bound += mn;
        }
        return bound;
    };
    struct Node { int level, cost, bound; vector<bool> assigned; };
    auto cmp = [](Node& a, Node& b) { return a.bound > b.bound; };
    priority_queue<Node, vector<Node>, decltype(cmp)> pq(cmp);
    vector<bool> init(n, false);
    pq.push({0, 0, calcBound(0, init, 0), init});
    int best = INT_MAX;
    while (!pq.empty()) {
        auto u = pq.top(); pq.pop();
        if (u.bound >= best) continue;
        if (u.level == n) { best = min(best, u.cost); continue; }
        for (int j = 0; j < n; j++) {
            if (!u.assigned[j]) {
                auto a = u.assigned; a[j] = true;
                int c = u.cost + cost[u.level][j];
                int b = calcBound(u.level+1, a, c);
                if (b < best) pq.push({u.level+1, c, b, a});
            }
        }
    }
    return best;
}

